      whyRevealing6: '洞見',
      twoPromptsSoundSimilar: '兩個聽起來相似的提示詞，在這個空間中可能相距很遠——反之亦然。alpha 滑桿在兩個提示詞（A 與 B）之間內插：0 時只有 A，1 時只有 B，大於 1 的值會外推超過 B。Spectral Strip 將全部 768 個維度顯示為長條，並允許直接操作個別維度。',
