      stableAudioUsesT5: 'Stable Audio 使用 T5-Base（768d）作為文字編碼器。內插在嵌入空間中進行：fused(α) = (1-α)·A + α·B。Magnitude 會縮放整個向量（數值越高 = 聲音越強烈），noise 會注入高斯雜訊以產生隨機變化。這個條件空間與 SD3.5 的在性質上不同：768 而非 4096 個維度，以音訊與文字配對、而非圖像與文字配對訓練。',
