      imageTextTogetherYield: '圖像與文字一起使用，能得到最豐富的結果。森林產生鳥鳴，街道產生交通噪音，吉他產生撥弦聲——直接的關聯，而不是繞道語言。最長 8 秒，44.1kHz，約 1.2 秒運算時間。',
