    story: '這裡要擴充的是圖像模型 Stable Diffusion 3.5。模型本身無法被改變，但可以為它加上一個 LoRA 模型：要學習的不是重新再學一次模型，而是少量的額外數值；一旦你的觸發詞出現在提示詞中，這些數值就會把輸出推向你的圖片。訓練之前，一個圖像描述模型會查看每一張上傳的圖片，並寫下它辨識出的內容——因此，機器辨識出的東西也參與決定了要學習什麼。',
    purpose: '這裡可以學到三件事：策展——從自己的素材中組成一個系列，並在資源稀少的條件下，為所選與所排除的內容提出美學上的理由。探測這項選擇中責任的各個面向。首先是對圖像素材的責任：它被加工成不再是圖像的東西。所有被描繪的事物都被抽離原本的脈絡，加工成一個龐大統計數字集合中的一小部分。其次是對訓練能源的責任：我們訓練一個 LoRA 的理由，應該要能為它所消耗的能源提出正當性。以及在實作中理解，一個大型圖像模型中什麼是固定的、什麼是可以附加上去的：模型學到的是風格還是內容，而它學到的是事先定義好的東西，還是別的東西？',
