    tokensUnavailable: '分詞器請求失敗，狀態 {status}：{reason}',
    noteBody: '編碼器融合會在圖像模型 Stable Diffusion 3.5 運算之前，改變模型據以計算圖像的那張數字表。兩個 CLIP 編碼器 CLIP-L 和 CLIP-G 填入上方 77 列，直到 4096 欄中的第 2047 欄，其後的欄保持為零。編碼器 T5-XXL 在下方填入 512 列，橫跨所有欄，提示詞的 T5 片段較多時則更多。每一列存放提示詞的一個片段、一個開始或結束標記，或文字結尾之後的填充。在這張表之外，模型還讀取池化向量：CLIP-L 的 768 個數字與 CLIP-G 的 1280 個數字串接而成。\n\nEsser et al.（2024）描述了 Stable Diffusion 3 中這張表的配置：CLIP 列以零填充至 4096 欄，T5 列置於其下方，並且在訓練中，三個編碼器各自隨機、彼此獨立地被設為零，因此在推論時，模型可以在它們的任何子集上運行。在他們的架構中，池化向量與模型所處的步驟是調變的兩項輸入：調變是模型每個區塊用來縮放和平移通過它的內容的那些數字（第 4 節）。對於 T5 區塊為零的表，也就是這裡的「僅 CLIP」，作者們報告「limited performance drops when using only the two CLIP-based text-encoders for the text prompts and replacing the T5 embeddings by zeros」，而詳細的場景描述與書寫文字則是例外。同時存放兩種編碼的一列（由正或負的 b 產生）位於這些受過訓練的狀態之外。模型會從這樣的表計算出什麼，就是這項工具的問題。',
