      headerSubtitleDetail: '八個用來研究擴散模型如何從文字生成圖像的工具。它們依介入的位置來排列。文字編碼器把你的提示詞轉成一個固定的嵌入，接著由這同一個嵌入引導全部 25 個去雜訊步驟。維度探索器、概念代數與編碼器融合在迴圈開始前改變嵌入一次，而編碼器融合工作臺沿著三個軸掃過融合參數。可組合擴散兩處都有：它把模型在每一個步驟傳回的結果組合起來，或在迴圈開始前於各概念的嵌入之間內插。去雜訊考古與注意力製圖什麼都不改變，只是觀看。Mean Images 同樣不動模型，而是把許多圖片平均成一張。對兩個 SD 3.5 模型，它在解碼器之前平均這些圖片的 latent。',
