      meanBlocked: '這一格的圖片全都通過了檢查。由它們做成的平均值，被一個圖像分析 AI 判定為不適合。',
      origin: 'Steyerl 寫道，在 mean images 中，「statistics are integrated directly into an object’s likeness, through determinations of likelinesses」（Steyerl 2025, p. 78）；也就是說，AI 模型是從機率計算出一件事物的圖像。在這個頁面上，你把 *mean method* 反過來用在（或用來對抗）生成式 AI 模型：從相似的提示詞，或從同一個提示詞配上不同的起始 Seed 生成許多圖像，再由所有這些圖像建立一個視覺上的「mean」，你就可以探索並比較視覺上的刻板印象、偏見，以及其他以統計方式製造「常態」的形式。',
      steyerl: '藝術家 Hito Steyerl 把 AI 模型生成的圖片稱為「mean images」、「a rendition of correlated averages」：由統計平均值做成的圖像。她寫道，英文的「mean」這個詞「has several meanings, all of which apply here」：「“Mean” may refer to minor or shabby origins, to the norm, to the stingy or to nastiness.」她寫道：「Mean images are far from random hallucinations. They are predictable products of data populism. They pick up on latent social patterns that encode conflicting significations as vector coordinates. They visualise real, existing social attitudes that align the common with lower-class status, mediocrity and nasty behaviour.」（Steyerl 2025, p. 72）',
