      unmarked: '基礎提示詞',
      noteBody: '圖像模型是用這樣的資料訓練的：世界上有些地方在其中出現數百萬次，有些則很少。訓練資料稀薄之處，模型就用常見的東西來填補空缺。當模型收到一次單獨的基礎提示詞、一次加上變化的提示詞時，這一點就變得可辨認。以「Seasons in January」為提示詞，三個模型中有兩個在 102 張圖片中的 102 張都傳回了北半球的冬天（Shin et al. 2024）。在帶有文化預期的提示詞上，44 % 的評分低於與提示詞完全相符，其中將近一半涉及隱含的文化預期（CULTURALFRAMES 基準測試，Nayak et al. 2025）。在該研究的例子中，一對伴侶接受父母的祝福，而父母卻不在圖像中。清單中的情緒是 Ekman 與 Friesen（1971）的六種基本情緒，在 Baron-Cohen、Golan、Wheelwright 與 Hill（2004）的分類法中，它們也是教學軟體「Mind Reading」的基礎。這項比較呈現出這些模型具有哪些情緒性的視覺建構，以及它們彼此之間差異有多大。',
