      techText: 'SD3.5 使用帶有聯合注意力（joint attention）的 MMDiT（Multimodal Diffusion Transformer）：圖像 token 與文字 token 在 24 個 transformer 區塊中彼此相互注意。我們在 3 個選定的區塊中，把預設的 SDPA 處理器換成手動的 softmax(QK^T/√d) 處理器，以擷取文字→圖像的注意力子矩陣。注意力圖的解析度為 64x64（patch 網格），再以雙線性插值放大到圖像解析度。SD3.5 有三個文字編碼器——CLIP-L（BPE，77 個 token）、CLIP-G（BPE，77 個 token）和 T5-XXL（SentencePiece，512 個 token）；其中兩個可以在這裡切換，以觀察不同的分詞策略如何影響注意力。',
