      headerTitle: '概念代數——圖像嵌入上的向量運算',
      headerSubtitle: '把著名的 word2vec 類比套用到圖像生成上：國王 − 男人 + 女人 ≈ 女王。',
      headerSubtitleDetail: '把著名的 word2vec 類比套用到圖像生成上：國王 − 男人 + 女人 ≈ 女王。三個提示詞會被編碼，並以代數方式組合。',
      explanationToggle: '顯示詳細說明',
      explainWhatTitle: '本工具呈現的內容',
      explainWhatText: '2013 年，Mikolov 指出詞嵌入會把語意關係編碼成線性方向：「國王」的向量減去「男人」再加上「女人」，得到的向量會接近「女王」。這個工具把這個想法套用到 SD3.5 的文字編碼器上：你操作的不是單一的詞，而是整個提示詞的嵌入。結果是一張沿著 B→C 方向離開 A 的圖像。它移動了多遠、在哪個面向上移動，正是這個工具讓你觀察的。',
      explainHowTitle: '代數的運作方式——以及與負向提示詞的差別',
      explainHowText: '你輸入三個提示詞：A（基礎）、B（減去）和 C（加上）。公式是：結果 = A − Scale₁×B + Scale₂×C。比例滑桿控制強度：在 1.0 時，B 會被完全減去，C 會被完全加上。在 0.5 時，只有一半。大於 1.0 的值會放大效果。——為什麼不直接用「A + C」當提示詞、用「B」當負向提示詞？因為兩者發生在不同的地方。負向提示詞是引導（guidance）據以衡量的基準，因此它在去雜訊迴圈之內作用，在 25 個步驟的每一步中，針對當下的圖像發揮作用。概念代數則是在生成「之前」計算出一個新向量：運算在嵌入空間中進行，只做一次，而迴圈永遠不會得知有任何東西被減去。——減法做不到的，是刪除一個被指名的物件。我們在本平臺上自己進行的一系列測量發現，從一個提示詞向量減去另一個提示詞向量，會改變色調、取景與語域，但被指名的東西仍留在圖像中。請把結果理解為意義空間中的位移，而不是移除。',
      explainReadTitle: '結果的意義',
      explainReadText: '左邊是參考圖像（只有提示詞 A，相同 Seed）。右邊是代數運算的結果。如果類比成立，右邊的圖像應該呈現概念 A，但帶有 B→C 的語意變化。例如：「海灘上的日落」−「海灘」+「山」≈「山上的日落」。L2 距離顯示結果離原始圖像移動了多遠。——這個運算有交換律嗎？沒有。B 的減去與 C 的加上，都是相對於向量 A 進行的。B→C 的方向只有在 A 的脈絡中才有意義：「國王 − 男人」從國王向量中移除「男性」方向，「+ 女人」加上「女性」方向——結果落在「女王」附近。C 並不是被精準地放在 B 被移除的位置；它只是被加上去。這樣仍然行得通，顯示語意關係在向量空間中被編碼為一致的線性方向。',
      techTitle: '技術細節',
