      headerTitle: '可組合擴散——每個概念各自的能量',
      headerSubtitle: '不再把整個提示詞編碼成一個整塊的單一向量，而是在去雜訊過程中讓每個概念各自通過一次 transformer。',
      headerSubtitleDetail: '不再把整個提示詞編碼成一個整塊的單一向量，而是在去雜訊過程中讓每個概念各自通過一次 transformer。每個概念再各自對圖像施加自己的拉力——或者，在權重為負時，把這股拉力減去。',
      explanationToggle: '顯示詳細說明',
      explainWhatTitle: '本工具的作用',
      explainWhatText: '標準的圖像生成會把你的整個提示詞壓縮成單一的表徵。模型把「湖邊的一棟紅色房子」看成一個融合在一起的概念。可組合擴散把它拆開：「紅色房子」和「湖」在每個去雜訊步驟中，各自完整地通過神經網路處理一次。它們的預測再以可調整的權重組合起來。這讓每個概念都有自己的「能量函數」——對圖像該是什麼樣子，各自投下自己的一票。也可以給一個概念負的權重。這時它不會被混合進去，而是在每個步驟中被減去，作為與正向概念並列、方向相反的一個方向。這能達成什麼，取決於被否定的是什麼：以物體形式出現在圖像中的物體可以被推出去；而在正向提示詞中綁定在某個物體上的屬性，或整個風格語域，則不會被移除——圖像只會退淡，在負權重很高時會失去內容，最後過度驅動。這也與負向提示詞是不同的運算：負向提示詞替換的是圖像據以衡量的基準。',
      explainHowTitle: '技術原理',
      explainHowText: '在 25 個去雜訊步驟的每一步，模型都執行 N+1 次 transformer 運算：一次用於負向提示詞（無條件），每個概念各一次。每個概念產生自己的雜訊預測——進入總和的並非該預測本身，而是它與無條件預測之間的差：noise = uncond + v1×(noise_1 - uncond) + v2×(noise_2 - uncond) + ... 每個 v 是該概念自己的引導強度。正的 v 把圖像拉向該概念（AND）；負的 v 把圖像推離該概念（NOT）。由於每個概念在每一步都被分別評分，沒有任何概念會被另一個概念吸收——而在單一融合的提示詞裡，發生的正是這種吸收。一次執行能結合相同概念的另一個位置是嵌入：在執行之前，這些概念的嵌入被內插成一個。方向從一個概念轉向另一個概念，長度則介於兩種讀取結果的長度之間。在這裡只有權重的比例起作用；有三個或更多概念時，概念排列的順序也會起作用。下一個概念所得的份額是 w2/(w1+w2)，而起作用的只有這個比例：把每個權重都乘以 -1，結果逐位元完全相同，因此 1.00 與 -2.00 得出的結果和 -1.00 與 2.00 相同。同號的權重使份額介於 0 與 1 之間，結果也落在概念之間。異號的權重則使份額落在這個範圍之外：1.00 與 -2.00 使總和為 -1、份額為 +2；2.00 與 -1.00 使份額為 -1。在範圍之外，結果不再位於概念之間。結果會越過權重在不計正負號時較大的那個概念，因此單憑負號看不出哪個概念被拋在後面；個別列會穿過零長度而消失，相鄰的列則被拉長。這樣一張表會畫出什麼，無法從數字讀出。從這裡開始，執行就是一般的執行，每一步兩次運算：一次用於這一個嵌入，一次用於負向提示詞。兩個位置的 Seed 與步數相同，因此以同一個 Seed 進行的兩次執行，差別在於位置。',
      techTitle: '技術細節',
      techText: '依據 Liu et al. (2022) 的式 11（合取）與式 15（否定）。每個概念都以 SD3.5 的全部三個編碼器（CLIP-L、OpenCLIP-G、T5-XXL）各自獨立編碼。自訂的去雜訊迴圈在每一步為每個概念呼叫一次 pipe.transformer()。在去雜訊器中，權重有兩種讀法。開啟「normalize」時，權重是 CFG 值的份額：總引導維持在 CFG，因此每加入一個概念，各自的份額就變小。關閉時，每個權重是該概念自己的引導溫度，v = CFG × 權重，負權重即 NOT 運算子——在代數上與論文中的 eps_u + w×(eps_a - eps_b) 完全相同。負權重會自動關閉正規化，因為帶正負號的混合沒有意義。在嵌入中兩種讀法都不適用：概念在那裡被內插，因此權重透過它與其他權重的比例起作用；有三個或更多概念時，概念排列的順序也會起作用。VRAM：模型權重在各次運算之間共用；只有激活值會變動。有 4 個概念時，生成時間約為標準的 4 倍（每一步需要 5 次 transformer 運算，而非 2 次）。',
