      weightHintDetail: '權重大於 0 會加入該概念（AND）。權重小於 0 會減去該概念（NOT）——這和把它放進負向提示詞並不相同。在嵌入中只有權重的「比例」起作用：下一個概念所得的份額是 w2/(w1+w2)，把每個權重都乘以 -1 不會改變任何結果，因此 1.00 與 -2.00 得出的結果和 -1.00 與 2.00 相同。兩個同號的權重使份額維持在 0 與 1 之間，結果也落在概念之間。兩個異號的權重則使份額落到這個範圍之外，此時結果會越過權重在不計正負號時較大的那個概念。',
