        explainWhatText: '依據 Zou et al. (2023)，《Representation Engineering: A Top-Down Approach to AI Transparency》（arXiv:2310.01405）。語言模型在書寫時，它即將說出的內容以一種由數字構成的狀態存在，一層接著一層。這個工具從該狀態中讀出一個方向——依據某人自己寫下的少數幾組句對——並在模型書寫時把這個方向加回該狀態。沒有任何東西被訓練：讀取與操控都在模型執行時發生。所用的方法只有 Zou et al. 的 reading vector：一個涵蓋整個隱藏狀態的方向，加到一個解碼器層的輸出上。Li et al. 的 Inference-Time Intervention（NeurIPS 2023）運作方式不同——每個注意力頭各有一個探針，而且只在能區分的頭上施加位移——因此它在 2026-08-24 從這個介面的文獻清單中移除。',
        explainHowTitle: '使用方式',
        explainHowText: '對比句對的處理分四個步驟。(1) 每一組句對都被讀取兩次：先把上面的句子交給模型，再交下面的句子，並在每個句子的最後一個 token 處，取出模型在層堆疊中間那一層的內部狀態。這組句對所貢獻的，是這兩個狀態之間的差。(2) 各組句對差值的共同之處就是方向。句對下方的圖呈現了這個方向：每組句對各有一支灰色箭頭，其角度是該組差值與共同方向之間的夾角；另有一支綠色箭頭代表共同方向本身——也就是被加入書寫過程的那一個。箭頭呈寬扇形散開，表示這些句對在好幾件事上不同，而讀取只保留它們共有的部分。(3) 方向會依句對本身沿著它移動的距離來縮放，因此強度以句對差值為單位計算：1 加入的量恰好等於一組句對平均相差的量，2 則把狀態推得比任何一組句子與其對應句的距離都還遠——這就是為什麼超過 2 時文字開始瓦解。軸從 1.5 開始，第一次按下就會讓答案翻轉。(4) 在模型書寫時，強度 × 方向會在每個 token 加到該解碼器層的輸出上，三個欄位分別呈現往一個方向推、不加干預、往另一個方向推的結果。為什麼會產生不實的句子：下一個詞只根據該狀態計算，而模型做出的每一個斷言，都來自狀態所在的位置。移動狀態，就移動了由它推導出的內容；推導出的內容是否碰巧為真，取決於狀態現在所在的位置，而那正是句對把它放置的地方。這個工具把斷言呈現為一個位置，而位置是可以移動的。為什麼中間欄沒有任何變化：零乘以方向是零向量，所以那裡完全沒有加入任何東西。那一欄是模型自己會產生的執行結果，作為解讀另外兩欄的參照。英文提示詞的效果明顯較好：大多數開放權重模型主要以英文訓練。',
        expectedResults: '預期結果：在「無箭頭」欄中，模型會照它自己的方式回答。在兩個外側欄中，模型從被移動過的狀態回答，其中一欄的答案通常不實——是哪一欄，取決於句對的共同之處。以這裡預設的三組句對而言，是「順著箭頭」那一欄：被推向上面的句子後，模型對關於德國的問題回答 Paris。',
        expectedResultsDetail: '一條軸，就在圖的正下方，範圍是 0.5 到 3 的距離，不帶正負號：每次按下時兩個方向都會執行，並呈現為兩個外側欄（「逆著箭頭」、「無箭頭」、「順著箭頭」）。軸從 1.5 開始，第一次按下就會讓答案翻轉。強度以句對差值為單位計算，所以 1 等於一組句對份量的推力；0.5 到 2 是可用的範圍，超過 2 就會被重複與無意義的內容占據。中間欄完全沒有加入任何東西——那是不加干預的模型，用來作為解讀另外兩欄的參照。每按一次，右側網格就會新增一列：三個格子來自同一次讀取與同一個 Seed，因此並排的兩個格子只在推力上不同，其他完全相同。每一列保留它開始時使用的提示詞，並標示一次推力的強度與所用的層。',
