        noteBody: '一組句對所貢獻的，是模型在其兩個句子上的狀態之差，而這些差值的共同之處就是方向（Zou et al. 2023）。在模型書寫時，本平臺會在每個 token 把方向的某個倍數加到中間層的輸出上。',
        advancedLabel: '進階設定',
        pairsSubtitle: '三組句對，每一組應只在一件事上不同（真與假）。',
        pairsSubtitleDetail: '三組句對，可編輯、有編號，每一組應只在一件事上不同。三組也是上限：到三組時，新增句對的按鈕就會消失。執行過一次後，句對會在欄位下方再以圖形呈現一次——每組句對各有一支灰色箭頭，各自編號，其角度是該組差值與共同方向之間的夾角；另有一支綠色箭頭代表那個共同方向，也就是被加入書寫過程的那一個。箭頭彼此靠近，表示這些句對在同一件事上不同；呈寬扇形散開，表示它們在好幾件事上不同，而讀取只保留它們的共同之處。這個排列是一種「投影」，而非手繪：三個差值彼此之間有三個夾角，而平面上從同一點出發的三條射線只有兩個自由參數，所以一張平面圖一次能保留三個夾角中的兩個。所畫的平面是讀取本身選出的那一個——沿著共同方向，以及橫越它的方向——而這個平面保留了多少比例的分散程度，每次執行都會回報。所有箭頭都畫成相同長度，因為在這裡，長度說明的會是圖本身，而不是句對。模型的權重自始至終保持不變：讀取與推動都在模型執行時發生。調換一組句對的兩個句子，對測量毫無影響——方向是外積總和的特徵向量，翻轉一個差值並不會改變它的外積——只會讓那一支箭頭反轉方向。',
