        targetLayerHintDetail: '這一層固定在層堆疊的中間，介面上沒有對應的控制項。深度決定同樣的推力會改變什麼：早期的層仍保有字詞本身，最後幾層已經保有下一個詞，而中間正是一個主張作為主張存在的地方——所以中間是唯一能產生可讀內容的設定，其他設定只會浪費一次執行。這一層取自所選的模型，因此會隨該模型層堆疊的深度而定；每一列結果都會回報它使用的層編號。介面上原本有一條用於此的軸，已於 2026-08-25 移除。',
