        explainWhatText: 'MMAudio（Cheng et al., CVPR 2025）以影片與音訊共同訓練。它不是先把圖像轉譯成文字、再轉成聲音，而是在同一個網路中把圖像與文字當作平行的訊號來處理。模型學到了哪些聲音屬於哪些視覺場景——森林產生鳥鳴，街道產生交通噪音，吉他產生撥弦聲。',
