  corefTest: {
    story: '當 AI 模型帶有偏見時，可能會令人不愉快，甚至很危險，因為它經常做出決定，或為決定做準備——例如警方使用的 AI。在這個頁面上，你們可以自己找出語言模型是否會傳遞偏見。這些英文句子的結構，讓人稱代名詞或關係代名詞（he/she/it, his/her/its）所指的對象是*明確的*。',
    purpose: '然而，語言模型在內部經常讀錯：雖然它們能很好地處理簡單句子的文法，但訓練進它們的偏誤與刻板印象，會讓它們在代名詞改變文法性別時，改變所指的對象。',
  },
  biasArchaeology: {
    story: '當 AI 模型帶有偏見時，可能會令人不愉快，甚至很危險，因為它經常做出決定，或為決定做準備——例如警方使用的 AI。在這個頁面上，你們可以自己找出語言模型是否會傳遞偏見。',
    purpose: '左欄中的所有問題都無法判定，所以「無法回答」永遠是正確答案。然而語言模型有時仍會選擇其他答案之一。找出它們這時是傾向符合偏見的答案，還是另一個答案。語言模型越常選擇偏見那一方，圖表下方的「偏誤分數」就爬得越高。這些問題來自「Bias Benchmark for QA dataset」（Parrish et al., Findings of ACL 2022；資料以 CC BY 4.0 授權，來自 github.com/nyu-mll/BBQ）。每次執行都會從每個類別最多 7,980 個開放問題中，重新隨機抽出 60 個。',
  },
