        purpose: '比較同一個提示詞在模型以另一種語言處理時會變成什麼。每一欄上方的回譯就是對此的檢查：大多數時候，回譯就是輸入的提示詞，所以翻譯是正確的，而圖像卻仍常常差異很大。SD 3.5 的文字部分是以英文文字訓練的；對於其他語言的提示詞，它們處理得極少，以至於語言本身決定了圖像，內容則退到後面。這時圖像呈現的是陳腔濫調：訓練資料中最常出現在該語言旁邊的東西。其他圖像模型透過它們各自的文字部分讀取提示詞，這些文字部分列在圖像模型下方的方框中。',
