        purpose: '聲音會演出性別與感受；這四個系統用完全不同的手段做到這一點。1995 年的機器裡沒有任何人的錄音；那裡是一條計算規則的十二種設定，但它聽起來仍常像某個人。在第二個系統中，每個聲音由一個檔案發聲，每個檔案都以一段錄音訓練，在所選檔案下方，若資料集有說明，就會寫出被錄音的人是誰。在第三個系統中，十個聲音各自在旁邊標示以赫茲表示的音高：比較標示 F 的和標示 M 的。第四個系統接收的不是清單，而是由三列組成的描述——性別、年齡、表達——；把設定與實際聽到的內容相比較。',
