        body: '1) eSpeak NG 1.51.1（1995）：AI 之前的電腦聲音。它以共振峰合成運作：規則把字母轉為音素，每個音素以少數幾個共振來播放。參見「speak」，Jonathan Duddington，1995。\n\n2) Piper 1.6.0（2022）：平行（VITS，2021：模型在一次運算中形成每個句子，並在每次執行時重新取樣音高與節奏）。每個聲音都是一個模型檔，以一個錄製的資料集訓練，已安裝的聲音大多是透過微調一個英語基礎聲音而來。可以選擇的是由哪個聲音模型發聲，聽到的說話者就是被錄音的那個人。（Michael Hansen，Rhasspy 專案，2022；所安裝的 1.6.0 來自 Home Assistant 的作者群，2026）在德語聲音「mls」中，236 位說話者被訓練進同一個模型檔。Piper 每次執行時以其中一位發聲。他們是為 LibriVox 錄製公有領域書籍的志工。研究語料庫 Multilingual LibriSpeech 收錄了他們的錄音。在「說話者」下方，下拉選單以每個人在語料庫中的編號標示他們，括號中是他們在檔案中的索引，並附上語料庫所記錄的性別與錄音量。\n\n3) Supertonic 3（2026）：9,900 萬個參數；非自迴歸（一個段落在一次運算中成形）。在語音自編碼器之上的 flow-matching 解碼器。十個聲音以向量形式訓練進模型中。它們可以透過簡單的加法與正規化來混合，例如 v = (v(F1) + v(F3) + v(M4)) / 3。（Supertone，2026）\n\n4) VoxCPM2（2026）：20 億個參數；擴散自迴歸（每個片段在其位置上去雜訊，並決定下一個片段如何被讀取，也會跨越句子邊界）。沒有參數；整個輸入都被當作語言讀取，關於聲音的指示嵌入在提示詞中並被理解。（OpenBMB，2026）',
